css:
.form {
  display: grid;
  gap: 12px;
  max-width: 360px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.row {
  display: grid;
  gap: 6px;
  padding: 12px;
  border-left: 4px solid transparent;
  border-radius: 6px;
}

.row:focus-within {
  border-left-color: #f97316;
  background-color: #fff7ed;
}

.input {
  padding: 8px 10px;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
  font: inherit;
}

.input:focus {
  outline: 2px solid #f97316;
  outline-offset: 1px;
}

.input:user-invalid {
  border-color: #dc2626;
  color: #b91c1c;
}

.hint {
  display: none;
  color: #71717a;
}

.input:placeholder-shown + .hint {
  display: block;
}
